function marketCap(price, supply){ price=+price; supply=+supply; if(!(price>=0)||!(supply>=0)) return {error:'价格与流通量须非负'}; return price*supply; }
function priceForCap(cap, supply){ cap=+cap; supply=+supply; if(!(supply>0)) return {error:'流通量须为正'}; return cap/supply; }
function valuation(owns, price){ return +owns*+price; }
function fdv(price, totalSupply){ return +price*+totalSupply; }
var EXPORTS={marketCap:marketCap, priceForCap:priceForCap, valuation:valuation, fdv:fdv};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MarketCapForgePure = EXPORTS; }
